/**
 * Resolves the rows a change points at. A row owned by another org is a
 * tenant violation; anything missing, archived or not a current member is
 * `not_found`.
 */
export async function requireActiveMember(
  actor: Actor,
  orgId: OrgId,
  userId: UserId,
  entity = "Member",
): Promise<Member> {
  assertOrgScope(actor, orgId);
  const member = await memberRepo.findMember(orgId, userId);
  if (!member || member.archivedAt !== null || member.status !== "active") {
    throw new NotFoundError(entity, userId);
  }
  return member;
}

export async function requireOrgLabels(
  actor: Actor,
  orgId: OrgId,
  labelIds: readonly LabelId[],
): Promise<void> {
  if (labelIds.length === 0) return;
  const found = await labelRepo.findLabelsByIdsUnscoped(labelIds);
  for (const id of labelIds) {
    const label = found.find((row) => row.id === id);
    if (!label) throw new NotFoundError("Label", id);
    assertOrgScope(actor, label.orgId);
    if (label.orgId !== orgId) throw new NotFoundError("Label", id);
  }
}

export async function requireParentIssue(
  actor: Actor,
  orgId: OrgId,
  projectId: ProjectId,
  parentId: IssueId,
): Promise<Issue> {
  const parent = await issueRepo.findIssueByIdUnscoped(parentId);
  if (!parent) throw new NotFoundError("Issue", parentId);
  assertOrgScope(actor, parent.orgId);
  if (
    parent.orgId !== orgId ||
    parent.projectId !== projectId ||
    parent.archivedAt !== null
  ) {
    throw new NotFoundError("Issue", parentId);
  }
  return parent;
}

